// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: caller address and unlockTime and deposit amount
    function testFuzz_property(address caller, uint256 unlockTime, uint256 amt) public {
        // keep amt reasonable so it can be sent and non-zero to exercise behavior
        amt = bound(amt, 0, 10 ether);
        // avoid zero-address caller because vm.prank with address(0) is awkward
        vm.assume(caller != address(0));

        // fund the caller so they can send ether
        vm.deal(caller, amt + 1 ether);

        // perform the Put call as the caller, with fuzzed unlockTime and amount
        vm.prank(caller);
        // call payable Put
        try c.Put{value: amt}(unlockTime) {
            // call succeeded
        } catch {
            // if the call reverts, we still want to assert the invariant on state readable from c
        }

        // Single assertion: for the correct reference implementation, Acc[caller].unlockTime >= block.timestamp
        // We use the public getter Acc to read the stored Holder struct's unlockTime (auto-generated getter)
        (uint storedUnlockTime, uint storedBalance) = c.Acc(caller);
        // The universal property: storedUnlockTime >= block.timestamp
        assertTrue(storedUnlockTime >= block.timestamp);
    }
}

