pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: actor address and provided unlockTime and deposit amount
    function testFuzz_property(address actor, uint256 providedUnlock, uint256 amt) public {
        // Keep actor as non-zero
        vm.assume(actor != address(0));
        // bound amount to a reasonable range and ensure at least 1 wei so payable path exercised
        amt = bound(amt, 1, 1 ether * 1000);
        // No need to bound providedUnlock; allow past/future values (the point of the test)

        // Fund actor and call Put with the fuzzed values
        vm.deal(actor, amt);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amt}(providedUnlock) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: if the call succeeded, the reference implementation guarantees
        // Acc[actor].unlockTime >= block.timestamp. We observe this through the public getter for Acc.
        // Read the stored unlockTime from the public mapping accessor auto-generated by Solidity.
        if (ok) {
            (, uint256 storedBalance, uint256 storedUnlock) = getHolder(actor);
            // single assertion: stored unlockTime is >= current block.timestamp
            assertTrue(storedUnlock >= block.timestamp);
        } else {
            // If call reverted, then nothing is required by the reference; still assert true trivially
            assertTrue(true);
        }
    }

    // helper to call the autogenerated getter: mapping (address => Holder) public Acc;
    // The compiler generates a function Acc(address) returns (uint unlockTime, uint balance)
    // but since solidity may order members differently, provide a wrapper that queries via low-level call to get full tuple.
    // Simpler: call the public accessor and adapt to its return ordering.
    function getHolder(address a) internal view returns (uint256 unlockTime, uint256 balance, uint256 pad) {
        // The public getter has signature Acc(address) returns (uint,uint) corresponding to (unlockTime,balance).
        // We call it and map results accordingly; pad is returned as 0 for compatibility with the tuple above.
        (uint256 u, uint256 b) = c.Acc(a);
        return (u, b, 0);
    }
}

