pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor address and an arbitrary unlock time and an arbitrary deposit amount
    function testFuzz_property(address actor, uint256 unlockTime, uint256 deposit) public {
        // Keep deposit reasonable so we can fund actor and send the tx
        deposit = bound(deposit, 0, 10 ether);
        // actor must be non-zero to be a realistic caller
        vm.assume(actor != address(0));

        // Fund the actor so they can send deposit
        vm.deal(actor, deposit);

        // Make the call as actor; call Put with fuzzed unlockTime and send fuzzed deposit
        vm.prank(actor);
        // If deposit is zero we still call (Put is payable)
        c.Put{value: deposit}(unlockTime);

        // Exactly one assertion: for the correct contract, after Put the stored unlockTime is at least block.timestamp
        // Read via public getter: Acc(actor).unlockTime is exposed by the public mapping accessor
        (, uint256 storedBalance) = getHolder(actor);
        // sanity: storedBalance must reflect deposit added (this isn't required by the problem but ensures actor interacted)
        // Now assert the universal property: stored unlockTime >= block.timestamp
        // We must read unlockTime via the public mapping getter on C: Acc(actor).unlockTime
        (uint256 recordedUnlockTime, ) = getHolder(actor);
        assertTrue(recordedUnlockTime >= block.timestamp);
    }

    // Helper to call the public generated getter for Acc mapping: the mapping was declared as `mapping (address => Holder) public Acc;`
    // The solidity auto-generated getter has the signature: function Acc(address) public view returns (uint unlockTime, uint balance);
    function getHolder(address a) internal view returns (uint256, uint256) {
        return c.Acc(a);
    }
}

