pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: attacker initial balance and deposit amount and unlockTime
    function testFuzz_property(uint256 attackerInitial, uint256 deposit, uint256 unlockTime) public {
        // keep values in reasonable ranges
        attackerInitial = bound(attackerInitial, 0, 10 ether);
        deposit = bound(deposit, 1 wei, 5 ether); // deposit must be >0 for effect
        // unlockTime can be any uint, keep it wide

        // deploy a re-entrant attacker that will call back into c during Put
        Attacker attacker = new Attacker(c);

        // fund attacker externally so it can send deposit
        vm.deal(address(attacker), attackerInitial + deposit);

        // ensure attacker will attempt reentrancy only when beneficial
        attacker.setAttackTarget(address(c));

        // perform Put from attacker, which is payable
        vm.prank(address(attacker));
        attacker.doPut{value: deposit}(unlockTime);

        // After Put completes, the invariant for the correct contract:
        // Acc[attacker].balance == deposit + previous balance (previous was 0 here)
        // We read the public mapping getter Acc to observe stored balance
        (uint unlock, uint bal) = c.Acc(address(attacker));

        // The reference contract with nonReentrant_ ensures the deposit is recorded
        // The mutant (without nonReentrant_) can be exploited by the attacker to reduce recorded balance
        assertTrue(bal >= deposit);
    }
}

// Minimal reentrant attacker: during receive(), it calls back to Put to try to disturb accounting.
contract Attacker {
    C public target;
    address public owner;
    bool public reentered = false;

    constructor(C _t) {
        target = _t;
        owner = msg.sender;
    }

    function setAttackTarget(address t) external {
        target = C(t);
    }

    // entrypoint used by test to trigger Put on target
    function doPut(uint _unlockTime) external payable {
        // call the target's Put using this contract as caller so that fallback/receive executes
        target.Put{value: msg.value}(_unlockTime);
    }

    // receive will try to reenter target.Put once to exploit lack of reentrancy guard
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to call Put again with 0 value to cause reentrancy during original Put
            // this call may succeed or change internal accounting in buggy mutant
            // we ignore return; it's used to disturb target state
            target.Put{value: 0}(0);
        }
    }
}

