pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: attacker initial balance and deposit amount and unlockTime
    function testFuzz_property(uint256 attackerInitial, uint256 deposit, uint256 unlockTime) public {
        // keep values in sensible wide ranges
        attackerInitial = bound(attackerInitial, 1 ether, 100 ether);
        deposit = bound(deposit, 1 wei, attackerInitial);

        // Deploy an attacker that will try to reenter Collect during Put by being the log contract
        Attacker attacker = new Attacker(address(c));

        // Fund attacker externally
        vm.deal(address(attacker), attackerInitial);

        // record prior stored balance (should be zero initially)
        uint256 prior = c.Acc(address(attacker));
        // call Put through the attacker so that attacker can attempt reentrancy if allowed
        vm.prank(address(attacker));
        (bool ok, ) = address(attacker).call{value: deposit}(abi.encodeWithSelector(Attacker.doPut.selector, unlockTime));
        require(ok, "external call failed");

        // read recorded balance via public getter: Acc returns Holder struct's first field (unlockTime) only
        // but the contract declares mapping (address => Holder) public Acc; which generates a getter returning both fields
        // so we can read balance by calling Acc(address)
        (, uint256 recordedBalance) = c.Acc(address(attacker));

        // The general invariant: recordedBalance == prior + deposit
        assertTrue(recordedBalance == prior + deposit);
    }
}

// Minimal adversarial helper that is used as the caller and also as the Log contract to allow reentrant behaviour.
// It will, during its call to C.Put, attempt to trigger a reentrant Collect if possible.
contract Attacker {
    C immutable target;
    bool reentered;

    constructor(address _t) {
        target = C(_t);
    }

    // entrypoint invoked by test to perform Put through this contract
    function doPut(uint256 unlockTime) external payable {
        // Call target.Put from this contract, sending along ETH
        // During the fallback from Put, the target will call LogFile.AddMessage which will call into this contract (since test setUp passed address(this) as log),
        // but to actually exercise reentrancy we make this contract be the caller so that fallback of C triggers Put again if non-reentrant removed.
        target.Put{value: msg.value}(unlockTime);
    }

    // Make this contract able to receive calls from C as the Log contract or via fallback and attempt reentrancy into Collect
    fallback() external payable {
        // try to reenter Collect to exploit lack of nonReentrant_ on Put in mutant
        if (!reentered) {
            reentered = true;
            // attempt to withdraw the whole recorded balance (if any)
            try target.Collect(address(this).balance) {
            } catch {
            }
        }
    }
}

