        uint256 amt = uint256(amount);
        vm.assume(actor != address(0));
        vm.deal(actor, amt);

        // record prior contract balance
        uint256 prior = address(c).balance;

        // perform Put as actor sending amt
        vm.prank(actor);
        bool ok;
        try c.Put{value: amt}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract (with nonReentrant_) ensures that if Put returns success
        // then the contract's balance increased by exactly amt and Acc[actor].balance >= amt.
