        // withdraw, making the contract balance not increase by full amt. We assert the
        // universal property that whenever Put returned successfully, address(c).balance == prior+amt.
        // This holds for the correct contract for all inputs; the mutant can fail for some inputs.
        if (ok) {
            assertTrue(address(c).balance == prior + amt);
        } else {
            // if Put reverted, nothing guaranteed about balances; still pass the test branch
            assertTrue(address(c).balance >= prior);
