pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // We fuzz: depositor address and deposit amount and unlockTime
    // Adversarial Log re-enters Collect during AddMessage to try to withdraw the deposit while Put is still executing
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address depositor, uint96 deposit, uint256 unlockTime) public {
        // keep depositor sane and non-zero
        vm.assume(depositor != address(0));
        // bound deposit to a reasonable non-zero value and ensure depositor has funds
        uint256 amt = bound(uint256(deposit), 1 ether / 1000, 10 ether);
        vm.deal(depositor, amt + 1 ether);

        // Deploy malicious Log that will re-enter Collect when AddMessage is invoked
        MaliciousLog ml = new MaliciousLog(address(c));
        // replace c's LogFile by deploying c with address(this) per instructions; but constructor already set Log to address(this)
        // We cannot change c.LogFile after deployment; instead we deploy a fresh C with the malicious log address.
        c = new C(address(ml));

        // ensure MinSum requirement: set deposit >= MinSum if needed; read MinSum from c
        uint256 minSum = c.MinSum();
        if (amt < minSum) {
            amt = minSum;
            vm.deal(depositor, amt + 1 ether);
        }

        // The malicious log will try to reenter Collect during Put. We perform Put from depositor sending amt.
        vm.prank(depositor);
        // call Put with fuzzed unlockTime
        bool ok;
        try c.Put{value: amt}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: after Put returns, contract's balance must be >= amt (the reference with nonReentrant_ prevents reentrant withdrawal during Put);
        // This expresses the universal property: for any admissible inputs and adversarial Log, reference keeps contract balance at least deposit after Put.
        // The mutant (without nonReentrant_ on Put) can be exploited by MaliciousLog to reenter and withdraw, making address(c).balance < amt for some inputs.
        assertTrue(address(c).balance >= amt);
    }
}

// Minimal adversarial Log: on AddMessage it will reenter Collect on the target contract to try to drain the depositor's balance.
contract MaliciousLog {
    C target;
    address attacker;
    constructor(address _target) {
        target = C(_target);
        attacker = msg.sender; // not used
    }

    // Signature must match AddMessage(address,uint,string)
    function AddMessage(address _adr, uint _val, string memory _data) public {
        // Try to withdraw: call Collect for _val if possible to attempt reentrancy during Put
        // ignore revert
        try target.Collect(_val) {
        } catch {
        }
    }
}

