pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: actor and amount. We check that after Put, the latest History entry's Val
    // equals the increment observed in Acc[actor].balance (i.e., the recorded log value matches the actual balance change).
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        // keep amount within reasonable bounds but wide
        amount = bound(amount, 0, 10 ether);
        // ensure amount is at least 1 wei so value-carrying calls are exercised; allow zero as well

        // prepare actor with funds
        vm.deal(actor, amount);
        // call Put as actor sending `amount` wei
        vm.prank(actor);
        c.Put{value: amount}(0);

        // Read the holder balance and the last logged message value
        (uint unlockTime, uint bal) = c.Acc(actor);
        // History is public array of Log.Message; History(length-1).Val equals last pushed Val
        // We obtain history length by calling History(uint) until revert is not needed: use try to call index 0 then binary
        // But simpler: access History( (uint) (c.LogFile().HistoryLengthEquivalent ) ) is not available.
        // However, in given C, History is public array, so History(uint) getter exists. We need the last index: try decreasing until found.

        // We can attempt to read index 0; if only one entry exists it's index 0. We'll search for the last by probing increasing indices until a revert occurs.
        uint idx = 0;
        // limit search to reasonable bounds
        for (uint i = 0; i < 64; i++) {
            try c.LogFile().History(i) returns (address, string memory, uint, uint) {
                idx = i;
                continue;
            } catch {
                // first revert means previous index was last
                if (i == 0) {
                    // no history entries — should not happen because Put pushes one
                    assertTrue(false);
                }
                idx = i - 1;
                break;
            }
        }

        (address sender, string memory data, uint val, uint time) = c.LogFile().History(idx);

        // The universal property: for ALL inputs, the reference contract records a History entry whose Val equals the amount that was added to Acc[actor].balance by that Put call.
        // We assert that the logged value equals the observed balance increase (here bal equals the increment because initial balance was zero in this test setup for actor).
        assertTrue(val == bal, "logged value must equal holder balance after Put");
    }
}

