pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor address and amount to send
    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount in a reasonable wide range but non-zero so Put does meaningful work
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 10 ether);

        // fund the actor so it can send
        vm.deal(actor, amount);

        // perform the Put call as the actor
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(block.timestamp + 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general invariant (single assertion): if the call succeeded, then
        // the last logged message's Val equals the increase in the actor's recorded balance.
        // We read c.Acc(actor).balance via auto getter and c.LogFile().History(last).Val
        if (ok) {
            // read balance
            uint bal = c.Acc(actor).balance;
            // There may be multiple history entries; get the last one index by querying length-1
            uint histLen = c.LogFile().History.length;
            // If there is at least one history entry, check the last's Val equals bal (since actor had no prior balance)
            // However, to keep this general if actor had prior deposits (unlikely in this test run), we compute delta.
            // For this test scenario actor starts with 0 in Acc (fresh test), so last.Val should equal bal.
            if (histLen > 0) {
                (address sender, string memory, uint val, uint) = c.LogFile().History(histLen - 1);
                // ensure the history entry corresponds to our actor
                assertTrue(sender == actor && val == bal);
            } else {
                // No history recorded -> fails property on mutant; ensure assertion fails here
                assertTrue(false);
            }
        } else {
            // If the call reverted, the reference implementation never reverts on valid funded Put,
            // but just to keep the single-assert rule, require ok==true for this test path
            assertTrue(false);
        }
    }
}

