pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount in reasonable range and non-zero to exercise payable behaviour
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 10 ether);

        // fund the actor and perform Put as that actor
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp + 1);

        // Read the latest History entry via auto-generated getter: History(index) returns (address,string,uint,uint)
        uint histLen = c.LogFile().HistoryLength();

        // If HistoryLength is zero, something went wrong; but reference always pushes one entry per Put
        // Compute observed last logged Val and the recorded balance
        (address sender,, uint loggedVal,) = c.LogFile().History(histLen - 1);
        uint recordedBalance = c.Acc(actor).balance;

        // The invariant: the most recent History entry's Val equals the amount sent and equals the increase in Acc[actor].balance
        // We express this as a single assert reading c's public surface: loggedVal == recordedBalance
        // (Because actor had zero balance before in general for fuzzed actor and we bounded amount; this holds for all actors created by fuzzer in this test environment)
        assertTrue(loggedVal == recordedBalance);
    }
}

// Minimal interface-compatible extensions for interacting with Log and Acc getters
interface LogLike {
    function History(uint i) external view returns (address, string memory, uint, uint);
    function HistoryLength() external view returns (uint);
}

// Extend C's external view surface via minimal wrappers using known public members names
contract C is C {}

