pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(address(this)); attacker = new Attacker(address(c)); }

    // fuzzed: amount to send and whether to use the attacker as caller
    function testFuzz_property(uint256 amount, bool useAttacker) public {
        // keep amount in a reasonable range and non-zero so Put does something
        amount = bound(amount, 1 wei, 10 ether);

        address caller = useAttacker ? address(attacker) : address(this);

        // Fund potential callers
        vm.deal(address(this), 20 ether);
        vm.deal(address(attacker), 20 ether);

        bool ok;
        if (useAttacker) {
            // attacker will call c.Put and reenter/observe behavior during the external LogFile.AddMessage call
            vm.prank(address(attacker));
            try c.Put{value: amount}(block.timestamp + 1) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            vm.prank(address(this));
            try c.Put{value: amount}(block.timestamp + 1) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // Single assertion: the last History entry's Sender equals the caller that invoked Put
        // Access LogFile via auto-generated getter: LogFile is public so we can read History( index )
        // But History is on Log contract; we only have c.LogFile() from C. The C contract's LogFile variable
        // is public, so C exposes a getter returning the Log contract address. We can then read its History(0)

        // Retrieve the Log contract address
        address logAddr = address(c.LogFile());
        // If no history entries exist, then ok may be false or nothing was recorded; require that when call succeeded
        // the last history entry's Sender equals the caller. We read History length via History(uint) auto getter by probing index 0.. bound; 

        // We attempt to read the most recent message by scanning backwards until we find a non-zero Sender or run out.
        // Limit scan to small number to avoid gas issues.
        Attacker.Log log = Attacker.Log(logAddr);
        uint foundIdx = type(uint).max;
        for (uint i = 0; i < 10; i++) {
            // try reading index from the end: History may be long; we approximate by checking decreasing indices from 9..0
            // Safer approach: check first 10 entries and pick the last non-zero Sender among them
            try log.History(i) returns (Attacker.Message memory m) {
                if (m.Sender != address(0)) {
                    foundIdx = i;
                }
            } catch {
                // ignore out-of-bounds
            }
        }

        // If no entry found among first 10, we still allow test to pass (no assertion on nonexistent data).
        if (foundIdx == type(uint).max) {
            // if call succeeded, reference contract would have logged; require ok==true to avoid vacuous pass
            // but we must have exactly one assertion; we therefore assert that either call failed or there is a log with matching sender.
            // Since we can't assert two conditions, we transform to: if call succeeded then there must be a matching entry at some index 0..9
            if (ok) {
                // force a failing assertion if no log found
                assertTrue(false);
            } else {
                assertTrue(true);
            }
            return;
        }

        // Read the found entry and check sender equals caller
        Attacker.Message memory last = log.History(foundIdx);
        assertTrue(last.Sender == caller);
    }
}

// Minimal helper attacker and log interface
contract Attacker {
    C public target;
    constructor(address _t) { target = C(_t); }

    // Mirror Log contract's Message struct and History getter signature to call it from the test
    struct Message { address Sender; string Data; uint Val; uint Time; }
    // Interface to read History entries from the Log contract
    interface Log { function History(uint) external view returns (Message memory); }

    // Fallback will try to reenter or do nothing; for this test we don't need active reentrancy logic,
    // but having a contract caller ensures msg.sender in Log.AddMessage is the attacker, revealing order differences.
    receive() external payable {}

    function doPut(uint unlockTime) external payable {
        target.Put{value: msg.value}(unlockTime);
    }
}

