contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // drive sequence: deposit from this contract, then call Collect and observe balance change
    // params: amount to deposit/collect (amt), unlockTime offset (utOffset)
    function run(uint amt, uint utOffset) public {
        // need some Ether to send
        require(address(this).balance >= amt, "insufficient balance");
        // ensure amt >= MinSum and >0
        uint min = c.MinSum();
        require(amt >= min && amt > 0, "amt too small");

        // deposit to c so msg.sender becomes this contract
        c.Put{value: amt}(block.timestamp + utOffset);

        // check recorded balance before collect
        uint before = c.Acc(address(this)).balance;

        // require unlock time passed so Collect can proceed: set utOffset = 0 means unlockTime = now, else we wait not possible here
        // enforce that unlockTime <= block.timestamp by calling Put with _unlockTime = block.timestamp
        // Caller used block.timestamp+utOffset; require utOffset == 0 to ensure unlocked
        require(utOffset == 0, "must be unlocked immediately");

        // attempt to collect full amount
        c.Collect{value: 0}(amt);

        // recorded balance after collect
        uint after = c.Acc(address(this)).balance;

        // Rule: the decrease (before - after) is <= amt and equals exactly amt when the transfer succeeded.
        // We assert the conservative general rule: before - after <= amt
        assert(before - after <= amt);
    }

    // allow contract to receive Ether for funding test
    receive() external payable {}
}

