        vm.deal(depositor, depositAmt);
        vm.prank(depositor);
        // call Put with unlockTime = block.timestamp (so any positive warp moves past it)
        c.Put{value: depositAmt}(block.timestamp);

        // advance time so unlockTime is passed
        vm.warp(block.timestamp + timeAdvance);

        // First Collect: should succeed on both reference and mutant (both call through nonReentrant require passes first time)
        bool firstOk;
        try c.Collect(firstAmt) {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        // Only proceed to second Collect attempt if first succeeded and remaining balance still >= MinSum and >= secondAmt
        // Read depositor's remaining balance from public getter Acc
        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(depositor);
        // admissible domain: we only assert property when first collect succeeded and remaining conditions hold
        // On the reference, if firstOk==true and balanceAfter>=c.MinSum() and balanceAfter>=secondAmt and block.timestamp>unlockTimeAfter
        // then the second Collect should succeed. The mutant that never resets locked_ will cause the second to revert.

        bool preconditions = firstOk && balanceAfter >= c.MinSum() && balanceAfter >= secondAmt && block.timestamp > unlockTimeAfter;

        bool secondOk;
        try c.Collect(secondAmt) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // Assert the universal property: for ALL admissible inputs (we only check when preconditions hold), the reference allows the second Collect.
        // The buggy mutant (locked_ never reset) will make secondOk == false for some inputs; this assertion should hold on the reference for all fuzz inputs.
        if (preconditions) {
            assertTrue(secondOk);
        }
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single public test function per rules
    // params: depositor (msg.sender for calls), deposit amount, withdraw amount, unlockTime
    function check(address depositor, uint depositAmount, uint withdrawAmount, uint unlockTime) public {
        // ensure this contract has enough ether to forward deposit and to pay potential gas
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        // 1) depositor is the caller for Put/Collect; we must call through c from this contract, so simulate depositor by calling c.Put from this contract.
        // The contract C records Acc[msg.sender], so to test for an arbitrary depositor address we'd need to call from that address; but per constraints we can use this contract as depositor.
        // So depositor parameter is only used to compare getters; ensure it's this contract for meaningful test
        require(depositor == address(this), "depositor must be this contract");

        // Make an initial deposit to create balance >= MinSum and set unlockTime in past or future as needed
        // We set unlockTime to a past value (0) or given unlockTime; choose provided unlockTime.
        c.Put{value: depositAmount}(unlockTime);

        // read balance before collect via public getter Acc(address).balance: Acc is public, returns Holder; Solidity auto-getter returns (uint unlockTime, uint balance)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // preconditions to ensure Collect will proceed and send funds: balance >= MinSum, balance >= withdrawAmount, and block.timestamp > unlockTime
        require(beforeBalance >= withdrawAmount, "beforeBalance < withdrawAmount");
        require(beforeBalance >= c.MinSum(), "beforeBalance < MinSum");
        require(block.timestamp > beforeUnlock, "unlock time not passed");

        // perform Collect which should transfer withdrawAmount and reduce recorded balance by withdrawAmount in original contract
        c.Collect{value: 0}(withdrawAmount);

        // read balance after
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // The invariant: beforeBalance == afterBalance + withdrawAmount
        assert(beforeBalance == afterBalance + withdrawAmount);
    }

    // allow contract to receive ether for deposit forwarding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am) public payable {
        require(true);
        uint before = address(c).balance;
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        uint after = address(c).balance;
        // If Collect did not revert, contract balance must have decreased by exactly _am
        assert(reverted || before == after + _am);
    }
    receive() external payable {}
}

