contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // caller must be this contract, so tests run from this contract's address
    function run(uint _am, uint _unlockTime, address payer) public payable {
        // Ensure this contract has enough Ether to let Collect succeed in sending funds out
        require(address(this).balance >= _am, "need ether to receive transfers");
        // Precondition: always allow; we will express rule via revert flag and public getters
        bool reverted;
        // Call Collect as this contract (msg.sender == address(this))
        try c.Collect{value: 0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Observe public getter Acc for this contract's address
        (uint unlockTime, uint balance) = c.Acc(address(this));
        // General rule: if stored balance and unlockTime permit a transfer of _am (balance>=c.MinSum, balance>=_am, and block.timestamp>unlockTime)
        // then Collect must not revert. Conversely, if those conditions do not hold, Collect may revert.
        assert(!((balance >= c.MinSum() && balance >= _am && block.timestamp > unlockTime) && reverted == true));
    }
    receive() external payable {}
}

contract InvMutTest {
